    const final = position === plan2.frames.length - 1;
    if (!final && now() > deadline)
      continue;
    const remaining = deadline - now();
    if (remaining > 0)
      await wait(remaining, signal);
    if (signal.aborted)
      break;
    if (!final && now() > deadline)
      continue;
